import re

ROW = re.compile(r'^(?P<cls>[A-Za-z_]\S*)\s+(?P<inst>\d+)\s+(?P<path>\S+)\s+(?P<drv>\S+)\s+(?P<sw>\S+)\s+(?P<hw>\S+)(?:\s+(?P<desc>\S.*?))?\s*$')
CONT = re.compile(r'^\s+(?P<files>/\S+(?:\s+/\S+)*)\s*$')
HDR = re.compile(r'^Class\s+I\s+H/W Path')

def parse(lines):
    records = []
    used = []
    skip = []
    cur = None
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if HDR.search(line):
            used.append(i)
            continue
        if re.match(r'^\s*[=\-]+\s*$', line):
            skip.append(i)
            continue
        m = CONT.match(line)
        if m and cur is not None:
            for f in m.group('files').split():
                key = 'Raw Device File' if '/rdsk/' in f or '/rdisk/' in f else 'Block Device File'
                cur[key] = (cur[key] + ' ' + f) if cur[key] else f
            used.append(i)
            continue
        m = ROW.match(line)
        if m:
            cur = {'Class': m.group('cls'), 'I': m.group('inst'), 'H/W Path': m.group('path'), 'Driver': m.group('drv'), 'S/W State': m.group('sw'), 'H/W Type': m.group('hw'), 'Description': m.group('desc') or '', 'Block Device File': '', 'Raw Device File': ''}
            records.append(cur)
            used.append(i)
            continue
    return {'blocks': [{'name': 'disks', 'kind': 'table', 'lines': used, 'records': records}], 'skip': skip}
